WORDS = {'title': ('أدوات وموارد', 'Outils et ressources', 'Tools & Resources'), 'intro': ('أدوات وموارد تقترحها الجمعية لفائدة منخرطيها. اطّلع على التفاصيل وأرسل طلبك للتواصل مع الإدارة.', 'Des outils et ressources proposés aux adhérents par l’association. Consultez les détails et envoyez votre demande.', 'Tools and resources proposed by the association for its members. Explore the details and send a request.'), 'more': ('معرفة المزيد', 'En savoir plus', 'Learn more'), 'request': ('طلب الأداة', 'Demander cet outil', 'Request this tool'), 'external': ('رابط الأداة', 'Lien vers l’outil', 'Tool link'), 'empty': ('ستُعرض الأدوات والموارد هنا بعد نشرها من طرف الجمعية.', 'Les outils et ressources apparaîtront ici après leur publication par l’association.', 'Tools and resources will appear here once published by the association.'), 'received': ('تم استلام طلبك. ستتواصل معك إدارة الجمعية عبر الهاتف أو البريد الإلكتروني لمتابعته.', 'Votre demande a été reçue. L’administration de l’association vous contactera par téléphone ou par e-mail pour y donner suite.', 'Your request has been received. The association administration will contact you by phone or email to follow up.'), 'private': ('تُستخدم معلوماتك لمتابعة طلب هذه الأداة والتواصل معك فقط، ولا تُنشر في الموقع. إرسال الطلب لا يعني تسليم الأداة أو تأكيد توفرها.', 'Vos coordonnées servent uniquement au suivi de cette demande et à vous contacter ; elles ne sont pas publiées. L’envoi ne garantit ni la disponibilité ni la remise de l’outil.', 'Your details are used only to follow up this tool request and contact you; they are not published. Submission does not guarantee availability or delivery.'), 'administration': ('إدارة الأدوات والموارد', 'Gestion des outils et ressources', 'Manage tools and resources'), 'requests': ('طلبات الأدوات', 'Demandes d’outils', 'Tool requests'), 'catalog': ('الأدوات المنشورة', 'Catalogue public', 'Public catalog'), 'add': ('إضافة أداة', 'Ajouter un outil', 'Add tool'), 'edit': ('تعديل الأداة', 'Modifier l’outil', 'Edit tool'), 'save': ('حفظ', 'Enregistrer', 'Save'), 'full_name': ('الاسم الكامل', 'Nom complet', 'Full name'), 'phone': ('رقم الهاتف', 'Téléphone', 'Phone number'), 'email': ('البريد الإلكتروني', 'E-mail', 'Email'), 'submitted': ('جديد', 'Nouvelle', 'New'), 'contacted': ('تم التواصل', 'Contact établi', 'Contacted'), 'closed': ('مغلق', 'Clôturée', 'Closed'), 'state': ('حالة الطلب', 'Statut de la demande', 'Request status'), 'notes': ('ملاحظات الإدارة الخاصة', 'Notes administratives privées', 'Private administration notes'), 'created_at': ('تاريخ الطلب', 'Date de la demande', 'Requested on'), 'all': ('كل الطلبات', 'Toutes les demandes', 'All requests'), 'published': ('نشر الأداة في الموقع', 'Publier l’outil sur le site', 'Publish tool on website'), 'sort_order': ('ترتيب الظهور', 'Ordre d’affichage', 'Display order'), 'website': ('رابط خارجي اختياري (HTTPS)', 'Lien externe facultatif (HTTPS)', 'Optional external link (HTTPS)'), 'image_file': ('صورة اختيارية (JPEG أو PNG، حتى 3 ميغابايت)', 'Image facultative (JPEG ou PNG, 3 Mio maximum)', 'Optional image (JPEG or PNG, up to 3 MiB)'), 'remove_image': ('إزالة الصورة الحالية', 'Retirer l’image actuelle', 'Remove current image'), 'image_notice': ('لا ترفع إلا صورة مخصصة للنشر العام ولديك حق استخدامها.', 'Utilisez uniquement une image destinée à la publication et dont vous détenez les droits d’utilisation.', 'Upload only an image intended for public display that you have the right to use.'), 'manual': ('الترجمات اختيارية وتُدخل يدويًا؛ يُعرض النص العربي عند غياب الترجمة. إلغاء النشر يخفي الأداة ويوقف طلباتها الجديدة مع الاحتفاظ بالطلبات السابقة.', 'Les traductions sont facultatives et manuelles ; le texte arabe est utilisé en leur absence. Dépublier masque l’outil et bloque les nouvelles demandes, tout en conservant les demandes existantes.', 'Translations are optional and manual; Arabic is displayed when a translation is missing. Unpublishing hides the tool and blocks new requests while preserving existing requests.'), 'saved': ('تم الحفظ.', 'Enregistré.', 'Saved.'), 'error': ('تعذّر الحفظ. راجع البيانات وأعد المحاولة.', 'Enregistrement impossible. Vérifiez les données et réessayez.', 'Could not save. Check the details and try again.'), 'expired': ('انتهت صلاحية الاستمارة أو تغير الطلب. أعد فتح الصفحة للمحاولة مجددًا.', 'Le formulaire a expiré ou la demande a changé. Rechargez la page pour réessayer.', 'The form expired or the request changed. Reopen the page to try again.'), 'limited': ('طلبات كثيرة. يرجى الانتظار قليلًا ثم المحاولة مجددًا.', 'Trop de demandes. Patientez avant de réessayer.', 'Too many requests. Please wait before trying again.'), 'next': ('التالي', 'Suivant', 'Next'), 'previous': ('السابق', 'Précédent', 'Previous'), 'open': ('فتح الطلب', 'Ouvrir la demande', 'Open request'), 'hidden': ('غير منشورة', 'Non publié', 'Unpublished'), 'title_ar': ('العنوان — العربية', 'Titre — arabe', 'Title — Arabic'), 'title_fr': ('العنوان — الفرنسية', 'Titre — français', 'Title — French'), 'title_en': ('العنوان — الإنجليزية', 'Titre — anglais', 'Title — English'), 'summary_ar': ('نبذة — العربية', 'Résumé — arabe', 'Summary — Arabic'), 'summary_fr': ('نبذة — الفرنسية', 'Résumé — français', 'Summary — French'), 'summary_en': ('نبذة — الإنجليزية', 'Résumé — anglais', 'Summary — English'), 'description_ar': ('تفاصيل الأداة — العربية', 'Détails de l’outil — arabe', 'Tool details — Arabic'), 'description_fr': ('تفاصيل الأداة — الفرنسية', 'Détails de l’outil — français', 'Tool details — French'), 'description_en': ('تفاصيل الأداة — الإنجليزية', 'Détails de l’outil — anglais', 'Tool details — English')}

def vocabulary(language):
    language = language if language in {"ar", "fr", "en"} else "ar"
    index = ("ar", "fr", "en").index(language)
    return language, {key: value[index] for key, value in WORDS.items()}
